// Extraer configuración del webhook
const input = $input.first().json;
return [{
  json: {
    keyword: input.keyword || input.niche || '',
    search_mode: input.search_mode || 'keyword',
    search_query: input.search_query || input.keyword || '',
    page_url: input.page_url || '',
    max_ads: input.max_ads || 20,
    dna_expert: input.dna_expert || '',
    dna_audience: input.dna_audience || '',
    dna_product: input.dna_product || '',
    objective: input.objective || '',
    cta: input.cta || '',
    telegram_chat_id: input.telegram_chat_id || '',
    email: input.email || '',
    likes_threshold: 1000
  }
}];

// Normalizar ads y extraer datos de competidores
const items = $input.all();
const ads = [];
const competitors = new Map();
const keyword = $('Config').first().json.keyword;
const threshold = $('Config').first().json.likes_threshold;

for (const item of items) {
  const ad = item.json;
  const pageName = ad.page_name || ad.advertiser_name || ad.snapshot?.page_name || '';
  const pageId = ad.page_id || ad.snapshot?.page_id || '';
  const pageUrl = ad.page_url || (pageId ? `https://www.facebook.com/${pageId}` : '');
  const pageLikes = ad.page_likes || ad.page_info?.likes || 0;

  // Filtrar por likes
  if (pageLikes < threshold && threshold > 0) continue;

  const adText = ad.ad_creative_body || ad.snapshot?.body?.text || ad.body || '';
  if (!adText || adText.length < 20) continue;

  // Agregar ad normalizado
  ads.push({
    ad_id: ad.id || ad.ad_id || '',
    page_name: pageName,
    page_url: pageUrl,
    page_id: pageId,
    ad_text: adText,
    headline: ad.ad_creative_title || ad.snapshot?.title || '',
    cta_text: ad.ad_creative_link_caption || '',
    start_date: ad.ad_delivery_start_time || ad.start_date || null,
    platform: ad.publisher_platform?.[0] || 'facebook',
    video_url: ad.video_url || ad.snapshot?.videos?.[0]?.video_url || null,
    image_url: ad.image_url || ad.snapshot?.images?.[0]?.original_image_url || null,
    page_likes: pageLikes
  });

  // Agregar competidor único
  if (pageId && !competitors.has(pageId)) {
    competitors.set(pageId, {
      fb_page_name: pageName,
      fb_page_url: pageUrl,
      fb_page_id: pageId,
      source_keyword: keyword
    });
  }
}

return [{
  json: {
    ads: ads,
    competitors: Array.from(competitors.values()),
    total_ads: ads.length,
    total_competitors: competitors.size
  }
}];

// Crear items individuales por cada competidor para upsert
const data = $input.first().json;
const competitors = data.competitors || [];

return competitors.map(c => ({ json: c }));

// Preparar ads para pipeline-model-ads
const data = $('Normalize + Extract Competitors').first().json;
const config = $('Config').first().json;

return [{
  json: {
    ads: data.ads,
    dna_expert: config.dna_expert,
    dna_audience: config.dna_audience,
    dna_product: config.dna_product,
    objective: config.objective,
    cta: config.cta,
    max_retries: 2,
    min_quality_score: 70
  }
}];

// Formatear resultado para respuesta
const pipeline = $input.first().json;
const config = $('Config').first().json;
const normData = $('Normalize + Extract Competitors').first().json;

return [{
  json: {
    success: true,
    keyword: config.keyword,
    total_ads_scraped: normData.total_ads,
    total_competitors: normData.total_competitors,
    scripts: pipeline.scripts || [],
    stats: pipeline.stats || {},
    message: `Procesados ${normData.total_ads} ads de ${normData.total_competitors} competidores`
  }
}];
